using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct NpcId : IEquatable<NpcId>, IComparable<NpcId>
    {
        public Guid Value { get; }

        public NpcId(Guid value)
        {
            Value = value;
        }

        public static NpcId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static NpcId NewRandom() => new NpcId(Guid.NewGuid());

        public static NpcId Parse(string text) => new NpcId(Guid.Parse(text));

        public static bool TryParse(string text, out NpcId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new NpcId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(NpcId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is NpcId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(NpcId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(NpcId left, NpcId right) => left.Equals(right);

        public static bool operator !=(NpcId left, NpcId right) => !left.Equals(right);
    }
}
